import java.io.*;
import static java.lang.System.*;
import java.lang.*;
import java.util.*;
import java.math.*;
import java.text.*;
public class AJ {
	
	public void run() throws Exception{
		Scanner file = new Scanner(new File("AJ.dat"));
		int times = file.nextInt();
		file.nextLine();
		while(times-- > 0) {
			char[] base = file.next().toCharArray();
			String hit = file.nextLine().trim(), o = "";
			if(hit.equals("Fly")) {
				if(base[2] == 'X')
					o += "3rd ";
				if(base[1] == 'X')
					o += "2nd ";
				if(base[0] == 'X')
					o += "1st ";
			}
			else if(hit.equals("Grounder")) {
				if(base[2] == 'X')
					o += "Home ";
				if(base[1] == 'X')
					o += "3rd ";
				if(base[0] == 'X')
					o += "2nd ";
				o += "1st ";
			}
			else
				o = "Give Up";
			if(o.length() == 0)o = "None";
			System.out.println(o.trim());
		}
	}
	
	public static void main(String[]args)throws Exception{
		new AJ().run();
	}
}

import java.io.File;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;

import static java.lang.System.out;


public class Micah {
    public static void main(String[] args) throws IOException {
        Scanner input = new Scanner(new File("micah_student.dat"));
        PrintWriter out = new PrintWriter(new File("micah_student.out"));
        int t = input.nextInt();

        for (int tc = 1; tc <= t; tc++) {
            int n = input.nextInt();
            int x = 0, y = 0;
            int minX = 0, maxX = 0, minY = 0, maxY = 0;
            int total = 0;
            int north = 0, south = 0, east = 0, west = 0;

            out.println("#########################");


            for (int i = 1; i <= n; i++) {
                String dir = input.next();
                int dist = input.nextInt();
                total += dist;

                if (dir.equals("N")) {
                    y += dist;
                    north++;
                } else if (dir.equals("S")) {
                    y -= dist;
                    south++;
                } else if (dir.equals("E")) {
                    x += dist;
                    east++;
                } else if (dir.equals("W")) {
                    x -= dist;
                    west++;
                }

                minX = Math.min(minX, x);
                maxX = Math.max(maxX, x);
                minY = Math.min(minY, y);
                maxY = Math.max(maxY, y);

                out.println("Leg " + i + " -> (" + x + "," + y + ")");
            }

            out.println();
            out.println("Final location : (" + x + "," + y + ")");
            out.println("Distance       : " + total);
            out.println("Bounds         : x = [" + minX + "," + maxX + "], y = [" + minY + "," + maxY + "]");
            out.println("Commands       : N=" + north + " S=" + south + " E=" + east + " W=" + west);
            out.println("#########################");
            out.println();
        }
        out.close();
        input.close();
    }
}

import java.io.File;
